struct string_buf {
    unsigned long long *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;
};

class stringx {
protected:
    char *chars;
    string_buf *my_buf;

public:
    int length() const;
    void lock();
    inline int size() const { return my_buf->char_length; }
    inline char &operator[](int index) {
        lock();
        if (index < 0)
            index += length();
        return chars[index];
    }
};

struct Glyph {
    char padding[12];
    int cell_width;
};

class Font {
public:
    bool unset;
    Glyph *getGlyph(char value);
};

class MultiLineString {
    Font *font;
    stringx text;

public:
    int getWidth();
};

__asm__(".equ lock__7stringx, 0x001D84D0");
__asm__(".equ length__C7stringx, 0x00144388");
__asm__(".equ getGlyph__4Fontc, 0x0033BD68");

int MultiLineString::getWidth()
{
    int max_width = 0;
    int curr_width = 0;

    if(font->unset)
        return 0;

    for(int i=0; i<text.size(); i++)
    {
        if(text[i] == '\n')
        {
            if(curr_width > max_width)
                max_width = curr_width;
            curr_width = 0;
        }
        else
            curr_width += font->getGlyph(text[i])->cell_width;
    }

    return curr_width > max_width ? curr_width : max_width;
}
